{
  "diagnosis": "The current rules lack a mechanism to prioritize tasks with high importance and sufficient evidence margin, leading to potential delays in addressing critical issues.",
  "skill": {
    "schema_version": "timing-skill-v1",
    "rules": [
      {
        "all": [
          {"field": "professional_available", "op": "eq", "value": true},
          {"field": "professional_signal", "op": "ge", "value": "kind_threshold"},
          {"field": "already_alarm", "op": "eq", "value": false},
          {"field": "importance", "op": "ge", "value": 0.75},
          {"field": "evidence_margin", "op": "positive", "value": 0.1}
        ]
      }
    ],
    "default_action": "CONTINUE_TOUR"
  },
  "expected_effect": "This skill prioritizes high-importance tasks with strong evidence, enabling earlier anomaly detection and reducing unnecessary detours."
}
